/// <reference types="vite/client" />
import { afterEach, describe, expect, it } from "vitest";
import samples from "../test_fixtures/explanation_samples.json";
import { setLocale } from "../locale";
import { presentBackendText as pb } from "./explanationPresent";

// samples.json was generated by importing backend/mineguard/explain.py (read-only): these are the backend's own sentences for 21 incident shapes.
type Sample = { resumen: string; decision: string; uncertainties: string[]; facts: string[]; steps: string[]; rule: string };
const S = samples as Sample[];
const SPANISH_LEFTOVERS = /\b(Resumen|simulado|regla|determinista|dejo|zona|estado final|proviene|motor|Evento|severidad|desde|hasta|Intervalo|desconocido|causas|Revisar|Confirmar|geometria|pixeles|explicacion|inspecciono|ningun|modelo y|fuente|Origen|analisis|camara|archivo|registro|almacen|origen)\b/;
afterEach(() => setLocale("es", false));

describe("simulated explanation presentation", () => {
  it("Spanish: every backend sentence is returned byte-for-byte", () => {
    setLocale("es", false);
    for (const c of S) {
      expect(pb(c.resumen, "summary")).toBe(c.resumen); expect(pb(c.decision, "decision")).toBe(c.decision); expect(pb(c.rule, "rule")).toBe(c.rule);
      c.facts.forEach((f) => expect(pb(f, "fact")).toBe(f)); c.uncertainties.forEach((u) => expect(pb(u, "uncertainty")).toBe(u)); c.steps.forEach((u) => expect(pb(u, "step")).toBe(u));
    }
  });
  it("English: every sentence of every incident shape is translated, and no Spanish is left", () => {
    setLocale("en", false);
    const bad: string[] = [];
    const check = (label: string, from: string, family: Parameters<typeof pb>[1]) => { const out = pb(from, family); if (out === from || SPANISH_LEFTOVERS.test(out)) bad.push(`${label}: ${out}`); };
    for (const c of S) {
      check("summary", c.resumen, "summary"); check("decision", c.decision, "decision"); check("rule", c.rule, "rule");
      c.facts.forEach((f) => check("fact", f, "fact")); c.uncertainties.forEach((u) => check("uncertainty", u, "uncertainty")); c.steps.forEach((u) => check("step", u, "step"));
    }
    expect(bad).toEqual([]);
  });
  it("English keeps every variable exactly (zone, state, rule id, engine version, times, causes)", () => {
    setLocale("en", false);
    expect(pb("Resumen simulado: la regla determinista dejo la zona Z1 en estado RED. Origen: simulacion con guion (sintetica, no es inferencia real).", "summary"))
      .toBe("Simulated summary: the deterministic rule left zone Z1 in state RED. Origin: scripted simulation (synthetic, not real inference).");
    expect(pb("El estado final RED proviene del motor de reglas determinista risk-1.2.", "decision")).toBe("The final state RED comes from the deterministic rule engine risk-1.2.");
    expect(pb("El estado final GREEN proviene del motor de reglas determinista.", "decision")).toBe("The final state GREEN comes from the deterministic rule engine.");
    expect(pb("Evento R-PV-01 severidad RED desde t=1.5 s hasta t=4.0 s.", "fact")).toBe("Event R-PV-01 severity RED from t=1.5 s to t=4.0 s.");
    expect(pb("Intervalo desconocido de t=0.0 s a t=2.0 s (causas: adapter_error).", "fact")).toBe("Unknown interval from t=0.0 s to t=2.0 s (causes: adapter_error).");
    expect(pb("Intervalo desconocido de t=2.0 s a t=3.0 s (causas: no indicadas).", "fact")).toBe("Unknown interval from t=2.0 s to t=3.0 s (causes: not specified).");
  });
  it("the simulated nature is never weakened in English", () => {
    setLocale("en", false);
    expect(pb(S[0].uncertainties[0], "uncertainty")).toBe("This explanation is simulated: no model was called and no video or images were inspected.");
    expect(pb(S[0].resumen, "summary")).toMatch(/^Simulated summary/);
  });
  it("an unknown sentence is shown exactly as received (never guessed), also in the wrong family", () => {
    setLocale("en", false);
    expect(pb("Se detectaron 7 personas adicionales a 12 metros.", "fact")).toBe("Se detectaron 7 personas adicionales a 12 metros.");
    expect(pb(S[0].resumen, "step")).toBe(S[0].resumen);
    expect(pb("", "fact")).toBe("");
  });
});
